    94	/** Remove live approval mutations before a historical result is persisted. */
    95	export function displaySafeMcpAppResult(value: unknown): unknown {
    96		if (Array.isArray(value)) return value.map(displaySafeMcpAppResult);
    97		if (!isRecord(value)) return value;
    98		return Object.fromEntries(
    99			Object.entries(value).map(([key, inner]) => {
   100				if (key === "actions" && Array.isArray(inner)) {
   101					return [
   102						key,
   103						inner
   104							.filter(
   105								(action) =>
   106									!isRecord(action) || action.tool !== "resolve_lobu_approval",
   107							)
   108							.map(displaySafeMcpAppResult),
   109					];
   110				}
   111				return [key, displaySafeMcpAppResult(inner)];
   112			}),
   113		);
   114	}
   115	
   116	/** Accept only small primitive interaction state; result data never flows here. */
   117	export function boundedMcpAppViewState(value: unknown): McpAppViewState {
   118		if (!isRecord(value)) return {};
   119		const state: McpAppViewState = {};
   120		for (const [key, inner] of Object.entries(value).slice(
   121			0,
   122			VIEW_STATE_MAX_KEYS,
   123		)) {
   124			if (!key || key.length > VIEW_STATE_KEY_MAX_LENGTH) continue;
   125			if (
   126				typeof inner !== "boolean" &&
   127				!(typeof inner === "number" && Number.isFinite(inner)) &&
   128				!(
   129					typeof inner === "string" &&
   130					inner.length <= VIEW_STATE_STRING_MAX_LENGTH
   131				)
   132			) {
   133				continue;
   134			}
   135			const candidate = { ...state, [key]: inner as boolean | number | string };
   136			if (Buffer.byteLength(JSON.stringify(candidate), "utf8") > VIEW_STATE_MAX_BYTES)
   137				break;
   138			state[key] = inner as boolean | number | string;
   139		}
   140		return state;
   141	}
   142	
   143	function parseSnapshot(body: string): SnapshotPayload | null {
   144		try {
   145			const parsed: unknown = JSON.parse(decrypt(body));
   146			if (
   147				!isRecord(parsed) ||
   148				parsed.version !== 1 ||
   149				typeof parsed.toolName !== "string" ||
   150				!isRecord(parsed.data)
   151			) {
   152				return null;
   153			}
   154			return {
   155				version: 1,
   156				toolName: parsed.toolName,
   157				data: parsed.data,
   158				viewState: boundedMcpAppViewState(parsed.viewState),
   159				...(typeof parsed.bindingKey === "string" &&
   160					/^[a-f0-9]{64}$/.test(parsed.bindingKey)
   161					? { bindingKey: parsed.bindingKey }
   162					: {}),
   163			};
   164		} catch {
   165			return null;
   166		}
   167	}
   168	
   169	function serializeSnapshot(payload: SnapshotPayload): {
   170		body: string;
   171		plaintextBytes: number;
   172	} | null {
   173		const plaintext = JSON.stringify(payload);
   174		const plaintextBytes = Buffer.byteLength(plaintext, "utf8");
   175		if (plaintextBytes === 0 || plaintextBytes > MCP_APP_RESULT_MAX_BYTES)
   176			return null;
   177		return { body: encrypt(plaintext), plaintextBytes };
   178	}
