\t\tbridge.callServerTool.mockImplementation(async ({ name }) => name === "save_lobu_app_state"
\t\t\t? { isError: false, structuredContent: { saved: true } }
\t\t\t: { isError: false, structuredContent: { found: false } });
\t\tconst { Provider, useMcpApp } = await import("./host");
\t\tfunction Probe() {
\t\t\tconst { data, setViewState } = useMcpApp<{ title: string }>();
\t\t\treturn <><span>{data?.title ?? "No result"}</span><button onClick={() => setViewState("details.open", true)}>Expand</button></>;
\t\t}
\t\trender(<Provider devMock={{ title: "dev" }}><Probe /></Provider>);
\t\texpect(await screen.findByText("No result")).toBeInTheDocument();
\t\tawait waitFor(() => expect(bridge.connect).toHaveBeenCalledTimes(1));
\t\tact(() => window.dispatchEvent(new CustomEvent("openai:set_globals", {
\t\t\tdetail: { globals: { toolOutput: { title: "Unpaired current card" } } },
