\t\texpect(await screen.findByText("Unpaired current card")).toBeInTheDocument();
\t\tbridge.callServerTool.mockClear();
\t\tfireEvent.click(screen.getByRole("button", { name: "Expand" }));
\t\tawait act(() => new Promise((resolve) => window.setTimeout(resolve, 300)));
\t\texpect(bridge.callServerTool).not.toHaveBeenCalledWith(expect.objectContaining({
\t\t\tname: "save_lobu_app_state",
\t\t\targuments: expect.objectContaining({ tool_call_id: "cleared-preload-card" }),
\t\t}));
\t});
'''
